using System.Net; using System.Text.Json; using InovaGed.Environment.Doctor.Quality;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class RouteSmokeQualityCheck:IQualityCheck {public string Name=>"Rotas";public async Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var config=Path.Combine(c.Root,"InovaGed.Environment.Doctor/quality-routes.json");var routes=JsonSerializer.Deserialize<string[]>(await File.ReadAllTextAsync(config,ct))??[];var dir=Path.Combine(c.Root,"artifacts/quality-gate");Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,"smoke-routes.ps1"),Script(routes,c.BaseUrl??"https://localhost:7282"),ct);if(string.IsNullOrWhiteSpace(c.BaseUrl))return[new(Name,QualityStatus.Warning,$"{routes.Length} rotas configuradas; smoke-routes.ps1 gerado.","Sem aplicação aberta, HTTP não foi executado.","Defina QUALITY_GATE_BASE_URL para smoke test ativo.",Resource:"artifacts/quality-gate/smoke-routes.ps1")];var r=new List<QualityFinding>();using var handler=new HttpClientHandler{ServerCertificateCustomValidationCallback=(_,_,_,_)=>true,AllowAutoRedirect=false};using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(15)};foreach(var route in routes)try{var response=await http.GetAsync(c.BaseUrl.TrimEnd('/')+route,ct);var status=response.StatusCode==HttpStatusCode.InternalServerError?QualityStatus.Fail:QualityStatus.Pass;r.Add(new(Name,status,$"{route} -> {(int)response.StatusCode}",status==QualityStatus.Fail?"Erro 500 em rota crítica.":null,"Consultar logs e corrigir a causa.",Resource:route));}catch(Exception e){r.Add(new(Name,QualityStatus.Fail,$"{route} -> {e.GetType().Name}","Rota crítica inacessível.","Iniciar a aplicação e revisar logs.",Resource:route));}return r;}private static string Script(IEnumerable<string> routes,string url)=>$"$baseUrl = \"{url}\"\n$routes = @(\n{string.Join(",\n",routes.Select(x=>$"  \"{x}\""))}\n)\nforeach ($route in $routes) {{\n try {{ $response = Invoke-WebRequest -Uri \"$baseUrl$route\" -UseBasicParsing -SkipCertificateCheck; Write-Host \"$route -> $($response.StatusCode)\" }} catch {{ Write-Host \"$route -> FAIL $($_.Exception.Message)\" }}\n}}\n";}
